{
  "skill_name": "waffle-solution-analyst",
  "evals": [
    {
      "id": 1,
      "name": "药企多事业部混合模式",
      "prompt": "我们正在和一个大型药企沟通，他们预计覆盖约8000名医药代表，但内部有不同规模的BU（小BU~100人，大BU~3000人，全员8000人）。这是首次合作，客户想先做200-500人的免费试玩验证效果，再决定是否正式采购。客户预算不确定但估计在30-50万区间。活动形式是抢地盘知识竞赛，可能有长周期运营（6个月/每月2天）和集中活动（年会配合）两种选择。客户还提到可能会对比其他游戏化供应商。请设计方案架构。",
      "assertions": [
        "区分了显性需求和隐性需求（至少识别2类隐性需求）",
        "判断合作模式为混合模式（试玩+可伸缩容量）或可伸缩容量模型",
        "设计至少2个容量档位",
        "包含试玩验证机制设计（人数/周期/边界/成本处理）",
        "包含价格保护规则（防套利）",
        "输出结构化方案摘要且包含报价分析师所需的参数"
      ]
    },
    {
      "id": 2,
      "name": "中小企业固定活动",
      "prompt": "一家200人的互联网公司想做一个企业文化知识竞赛，用于年会活动。只需要1天，实时对战模式，不需要AI分析，预算约3-5万。需求很明确——年会上大家一起答题活跃气氛，配合主会场大屏展示。不需要试玩，直接签合同做。请设计方案架构。",
      "assertions": [
        "判断合作模式为固定活动方案",
        "没有过度设计容量分层（只输出单方案而非多档位）",
        "包含方案摘要结构且包含报价参数（人数/周期/形式等）"
      ]
    },
    {
      "id": 3,
      "name": "金融机构复购订阅",
      "prompt": "一家大型银行去年和我们合作过一次校招保温活动（2000人，效果很好）。现在他们培训部想长期使用Waffle做全年的销售知识训练，覆盖约5000名理财经理。希望每个季度做一次活动，持续一年。他们也需要AI能力（知识图谱+人才画像），预算约40-60万。另外他们IT部门问能否本地部署。请设计方案架构。",
      "assertions": [
        "正确识别为复购客户并体现在方案设计中",
        "判断合作模式符合平台订阅或长周期特征",
        "包含AI能力升级路径建议（针对复购客户）",
        "方案摘要结构完整且包含报价参数"
      ]
    }
  ]
}

